// Specification of the k-th prefix running counter:
// prefix_value(s, k) = sum over s[0..k): +1 for 'I', -1 for 'D'.
#[verifier(spec)]
pub fn prefix_value(s: Seq<char>, k: nat) -> int {
    if k == 0 {
        0
    } else {
        let prev = prefix_value(s, k - 1);
        if s.index(k - 1) == 'I' {
            prev + 1
        } else {
            prev - 1
        }
    }
}

// Specification of the maximum running counter over all prefixes of s.
// max_running_spec(s) = max_{0 <= k <= s.len()} prefix_value(s, k)
#[verifier(spec)]
pub fn max_running_spec(s: Seq<char>) -> int {
    if Seq::len(s) == 0 {
        0
    } else {
        let k = Seq::len(s);
        let mprev = max_running_spec(Seq::slice(s, 0, k - 1));
        let last = prefix_value(s, k);
        if mprev > last {
            mprev
        } else {
            last
        }
    }
}

